class Solution {
    public String reformatDate(String date){
        String[] parts=date.split(" ");
        List<String> months=Arrays.asList("Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec");
        int day=Integer.parseInt(parts[0].substring(0,parts[0].length()-2)),month=months.indexOf(parts[1])+1,year=Integer.parseInt(parts[2]);
        return String.format("%04d-%02d-%02d",year,month,day);
    }
}

code.kotlin:
class Solution {
    fun reformatDate(date:String):String{
        val parts=date.split(' ');
        val months=listOf("Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec");
        val day=parts[0].dropLast(2).toInt();
        val month=months.indexOf(parts[1])+1;
        return "%04d-%02d-%02d".format(parts[2].toInt(),month,day)
    }
}

code.cpp:
class Solution {
    public: string reformatDate(string date){
        stringstream stream(date);
        string dayToken,monthToken,year;
        stream>>dayToken>>monthToken>>year;
        vector<string> months={
            "Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"
        };
        int day=stoi(dayToken),month=find(months.begin(),months.end(),monthToken)-months.begin()+1;
        char buffer[11];
        snprintf(buffer,sizeof(buffer),"%04d-%02d-%02d",stoi(year),month,day);
        return buffer;
    }
};
